--
-- Table structure for table `ld_customform13`
--

DROP TABLE IF EXISTS `ld_customform13`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_customform13` (
  `customform13id` int(19) NOT NULL DEFAULT '0',
  `customform13_no` varchar(255) DEFAULT NULL,
  `smownerid` int(19) DEFAULT NULL,
  `smcreatorid` int(19) DEFAULT NULL,
  `createdtime` datetime DEFAULT NULL,
  `modifiedby` int(19) DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `approvestatus` varchar(50) DEFAULT '未提交',
  `approvetime` datetime DEFAULT NULL,
  `approveby` int(19) DEFAULT NULL,
  `currentapprover` text,
  `print_times` int(11) DEFAULT '0',
  `total` decimal(25,8) DEFAULT NULL,
  `subtotal` decimal(25,8) DEFAULT NULL,
  `adjustment` decimal(25,8) DEFAULT NULL,
  `discount_type` int(1) DEFAULT '0',
  `discount_percent` decimal(25,3) NOT NULL DEFAULT '0.000',
  `discount_amount` decimal(25,8) DEFAULT NULL,
  `s_h_amount` decimal(25,3) DEFAULT NULL,
  `currency_id` int(19) DEFAULT '1',
  `conversion_rate` decimal(25,6) DEFAULT '1.000000',
  `currency_symbol` varchar(30) DEFAULT '¥',
  `deleted` int(19) NOT NULL DEFAULT '0',
  `accountid` int(19) DEFAULT '0',
  `source_list` text,
  `entitytype` varchar(50) DEFAULT NULL,
  `potentialid` int(19) DEFAULT '0',
  `contactid` int(19) DEFAULT '0',
  `customform03_id` int(19) DEFAULT '0',
  `customform04_id` int(19) DEFAULT '0',
  `pricebooksid` int(19) DEFAULT '0',
  `advance_stage` varchar(100) DEFAULT NULL,
  `approvesubmitter` int(19) DEFAULT '0',
  `approvesubmittedtime` datetime DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT 'no',
  `approveexpediting` varchar(10) DEFAULT 'no',
  `currentapprovestepid` int(19) DEFAULT '0',
  `team_memberid` text,
  `tag` varchar(50) DEFAULT NULL,
  `kis_id` varchar(200) DEFAULT NULL,
  `kis_no` varchar(200) DEFAULT NULL,
  `exchtime` datetime DEFAULT NULL,
  `exchmsg` text,
  `latestpushtime` datetime DEFAULT NULL,
  `received_amount` decimal(25,8) DEFAULT NULL,
  `receivable_balance` decimal(25,8) DEFAULT NULL,
  `pay_amount` decimal(25,8) DEFAULT NULL,
  `pay_balance` decimal(25,8) DEFAULT NULL,
  `triggercount` int(19) DEFAULT '0',
  `product_licence_price` decimal(25,2) DEFAULT '0.00',
  `cumulative_benefits` decimal(25,2) DEFAULT '0.00',
  PRIMARY KEY (`customform13id`),
  KEY `accountid` (`accountid`),
  KEY `approvestatus` (`approvestatus`),
  KEY `createdtime` (`createdtime`),
  KEY `modifiedtime` (`modifiedtime`),
  KEY `smcreatorid` (`smcreatorid`),
  KEY `smownerid` (`smownerid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

