mount,\n			now_invoice.tax_amount AS now_tax_amount\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'季度\' THEN\n							QUARTER (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time,\n					where_table.where_time AS where_time\n				FROM\n					tmp_date,\n					(\n						SELECT\n							YEAR (\n								DATE_ADD(\n									\'{starttime}\',\n									INTERVAL seq YEAR\n								)\n							) where_time\n						FROM\n							sequence\n						WHERE\n							YEAR (\n								DATE_ADD(\n									\'{starttime}\',\n									INTERVAL seq YEAR\n								)\n							) <= YEAR (\'{endtime}\')\n					) where_table\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					where_time,\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				ld_invoice.invoiceid,\n				YEAR (ld_invoice.invoicedate) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'月\' THEN\n						MONTH (ld_invoice.invoicedate)\n					WHEN \'{timetype}\' = \'季度\' THEN\n						QUARTER (ld_invoice.invoicedate)\n					ELSE\n						MONTH (ld_invoice.invoicedate)\n					END\n				) AS group_time,\n				sum(\n					now_s_detail.tax_amount / ld_invoice.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_invoice\n			LEFT JOIN ld_invoicedetail now_s_detail ON now_s_detail.id = ld_invoice.invoiceid\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_invoice.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_invoice.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_invoice.invoicedate BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_invoice ON now_invoice.group_time = timetype_table.group_time\n		AND now_invoice.where_time = timetype_table.where_time\n		LEFT JOIN (\n			SELECT\n				ld_invoice.invoiceid,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 MONTH\n							)\n						)\n					WHEN \'{timetype}\' = \'季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 MONTH\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'月\' THEN\n						MONTH (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 MONTH\n							)\n						)\n					WHEN \'{timetype}\' = \'季度\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						MONTH (\n							DATE_ADD(\n								ld_invoice.invoicedate,\n								INTERVAL 1 MONTH\n							)\n						)\n					END\n				) AS group_time,\n				sum(\n					pre_s_detail.tax_amount / ld_invoice.conversion_rate\n				) AS tax_amount\n			FROM\n				ld_invoice\n			LEFT JOIN ld_invoicedetail pre_s_detail ON pre_s_detail.id = ld_invoice.invoiceid\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_invoice.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_invoice.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_invoice ON pre_invoice.group_time = timetype_table.group_time\n		AND pre_invoice.where_time = timetype_table.where_time\n		GROUP BY\n			timetype_table.where_time,\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.where_time,\n	p_num.group_time','Default',NULL,NULL,'product_invoice_amount_m_to_m'),(321,'产品出库数量环比','','sqlchart',NULL,0,NULL,'2023-11-24 11:43:57','2023-11-28 19:29:27',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',75,'SELECT\n	(\n		CASE\n		WHEN \'{timetype}\' = \'季度\' THEN\n			CONCAT(\n				p_num.where_time,\n				\'-\',\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			DATE_FORMAT(\n				STR_TO_DATE(\n					CONCAT(\n						p_num.where_time,\n						\'-\',\n						p_num.group_time\n					),\n					\'%Y-%m\'\n				),\n				\'%Y-%m\'\n			)\n		END\n	) AS dispaly_group_time,\n	sum(p_num.pre_num) AS pre_num,\n	sum(p_num.now_num) AS now_num\nFROM\n	(\n		SELECT\n			timetype_table.group_time AS group_time,\n			timetype_table.where_time AS where_time,\n			pre_outboundorder.quantity AS pre_num,\n			now_outboundorder.quantity AS now_num\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'月\' THEN\n							MONTH (date)\n						WHEN \'{timetype}\' = \'季度\' THEN\n							QUARTER (date)\n						ELSE\n							MONTH (date)\n						END\n					) AS group_time,\n					where_table.where_time AS where_time\n				FROM\n					tmp_date,\n					(\n						SELECT\n							YEAR (\n								DATE_ADD(\n									\'{starttime}\',\n									INTERVAL seq YEAR\n								)\n							) where_time\n						FROM\n							sequence\n						WHERE\n							YEAR (\n								DATE_ADD(\n									\'{starttime}\',\n									INTERVAL seq YEAR\n								)\n							) <= YEAR (\'{endtime}\')\n					) where_table\n				WHERE\n					date LIKE \'%2023%\'\n				GROUP BY\n					where_time,\n					group_time\n			) timetype_table\n		LEFT JOIN (\n			SELECT\n				ld_outboundorder.out_id,\n				YEAR (ld_outboundorder.outdate) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'月\' THEN\n						MONTH (ld_outboundorder.outdate)\n					WHEN \'{timetype}\' = \'季度\' THEN\n						QUARTER (ld_outboundorder.outdate)\n					ELSE\n						MONTH (ld_outboundorder.outdate)\n					END\n				) AS group_time,\n				sum(now_s_detail.quantity) AS quantity\n			FROM\n				ld_outboundorder\n			LEFT JOIN ld_outboundorderdetail now_s_detail ON now_s_detail.id = ld_outboundorder.out_id\n			LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.smownerid,\n				\'{userscope}\'\n			)\n			AND (\n				ld_outboundorder.outdate BETWEEN \'{starttime}\'\n				AND \'{endtime}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) now_outboundorder ON now_outboundorder.group_time = timetype_table.group_time\n		AND now_outboundorder.where_time = timetype_table.where_time\n		LEFT JOIN (\n			SELECT\n				ld_outboundorder.out_id,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'月\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 MONTH\n							)\n						)\n					WHEN \'{timetype}\' = \'季度\' THEN\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						YEAR (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 MONTH\n							)\n						)\n					END\n				) AS where_time,\n				(\n					CASE\n					WHEN \'{timetype}\' = \'月\' THEN\n						MONTH (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 MONTH\n							)\n						)\n					WHEN \'{timetype}\' = \'季度\' THEN\n						QUARTER (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 QUARTER\n							)\n						)\n					ELSE\n						MONTH (\n							DATE_ADD(\n								ld_outboundorder.outdate,\n								INTERVAL 1 MONTH\n							)\n						)\n					END\n				) AS group_time,\n				sum(pre_s_detail.quantity) AS quantity\n			FROM\n				ld_outboundorder\n			LEFT JOIN ld_outboundorderdetail pre_s_detail ON pre_s_detail.id = ld_outboundorder.out_id\n			LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n			WHERE\n				(\n					ld_products.productname = \'{productname}\'\n					OR \'{productname}\' = \'\'\n				)\n			AND (\n				\'{productcategory}\' = \'\'\n				OR FIND_IN_SET(\n					ld_products.productcategory,\n					\'{productcategory}\'\n				)\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.approvestatus,\n				\'{approvestatus}\'\n			)\n			AND FIND_IN_SET(\n				ld_outboundorder.smownerid,\n				\'{userscope}\'\n			)\n			GROUP BY\n				where_time,\n				group_time\n		) pre_outboundorder ON pre_outboundorder.group_time = timetype_table.group_time\n		AND pre_outboundorder.where_time = timetype_table.where_time\n		GROUP BY\n			timetype_table.where_time,\n			timetype_table.group_time\n	) p_num\nGROUP BY\n	p_num.where_time,\n	p_num.group_time','Default',NULL,NULL,'product_outboundorder_quantity_m_to_m'),(322,'产品出库金额环比','','sqlchart',NULL,0,NULL,'2023-11-24 11:48:46','2023-11-28 19:30:46',0,1,NULL,NULL,NULL,1,NULL,0,'yes','no','no',NULL,'yes','Bottom',75,'SELECT\n	(\n		CASE\n		WHEN \'{timetype}\' = \'季度\' THEN\n			CONCAT(\n				p_num.where_time,\n				\'-\',\n				\'第\',\n				p_num.group_time,\n				\'季度\'\n			)\n		ELSE\n			DATE_FORMAT(\n				STR_TO_DATE(\n					CONCAT(\n						p_num.where_time,\n						\'-\',\n						p_num.group_time\n					),\n					\'%Y-%m\'\n				),\n				\'%Y-%m\'\n			)\n		END\n	) AS dispaly_group_time,\n	sum(p_num.pre_tax_amount) AS pre_tax_amount,\n	sum(p_num.now_tax_amount) AS now_tax_amount\nFROM\n	(\n		SELECT\n			timetype_table.group_time AS group_time,\n			timetype_table.where_time AS where_time,\n			pre_outboundorder.tax_amount AS pre_tax_amount,\n			now_outboundorder.tax_amount AS now_tax_amount\n		FROM\n			(\n				SELECT\n					(\n						CASE\n						WHEN \'{timetype}\' = \'月\' THEN\n					