INSERT INTO `ld_mailmanager_mailrecord` VALUES (276,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'AFUACwALB3PQ*rjs46jxUqoO',NULL,NULL,NULL,0,0,1,'pjs@kingdisplay.com',0,'2019-08-26 15:30:46',NULL,'pop'),(276,'tanhaiyuan <tanhaiyuan@kingdisplay.net.cn>','向鹏生 <xiangpengsheng@kingdisplay.net.cn>,姚奕兰<yyl@kingdisplay.net.cn>,姜平<jiangp@kingdisplay.net.cn>,孙绪生<sunxusheng@kingdisplay.net.cn>,廖声花<lsh@kingdisplay.net.cn>,张建军<zhangjianjun@kingdisplay.net.cn>,张阳<zhy@kingdisplay.net.cn>,彭军帅<pjs@kingdisplay.net.cn>,彭红','冯翠 <fc@kingdisplay.net.cn>,吴友丽<wyl@kingdisplay.net.cn>,周艳<zy@kingdisplay.net.cn>,甘明华<ganminghua@kingdisplay.net.cn>,胡育源<bendyhu@kingdisplay.net.cn>,郑琦林<zql@kingdisplay.net.cn>,郭维凌<clarekuo@kingdisplay.com>,dujianxin<dujianxin@kingdisplay.com>,yangqunji<yangqunji@kingdisplay.com>,nixiaoling<nixiaoling@kingdisplay.com>',NULL,'2019-08-26 10:28:17','截止8月26号已完工未结案生产&委外工单','<html><head><meta http-equiv=\"content-type\" content=\"text/html; charset=GB2312\"><style>body { line-height: 1.5; }p { margin-top: 0px; margin-bottom: 0px; }body { font-size: 10.5pt; font-family: Tahoma; color: rgb(0, 0, 0); line-height: 1.5; }body { font-size: 10.5pt; font-family: Tahoma; color: rgb(0, 0, 0); line-height: 1.5; }</style></head><body>\n<div><span></span><div><span style=\"font-size: 16px; line-height: 1.5; background-color: transparent;\">大家好：</span></div><div><div style=\"position: static !important;\"><div style=\"position: static !important;\"><div style=\"position: static !important;\"><div style=\"position: static !important;\"><span style=\"font-size: 16px;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 截止2019.8.26号<font color=\"#ff0000\">（工单未入库数量为0的）未结案</font>工单（明细见附件）：</span></div><div style=\"position: static !important;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp; &nbsp; 1.<span style=\"background-color: rgb(255, 255, 0);\">生产订单</span>未结案：总计194张（其中：深圳25张+蚌埠169张），请在完工后的2天之内将退、补料完成、办理结案，逾期未完成结案的有155张（其中：<span style=\"background-color: transparent;\">深圳5张+蚌埠</span><span style=\"background-color: transparent;\">150</span><span style=\"background-color: transparent;\">张</span><span style=\"background-color: transparent;\">）；</span></span></div><div style=\"position: static !important;\"><span style=\"font-size: 16px;\"><span style=\"line-height: 1.5; background-color: transparent;\">&nbsp; &nbsp; &nbsp; 2.</span><span style=\"line-height: 1.5; background-color: rgb(255, 255, 0);\">委外订单</span><span style=\"line-height: 1.5; background-color: transparent;\">未结案：</span><span style=\"background-color: transparent;\">总计399张</span></span><span style=\"font-size: 16px; line-height: 24px;\">（其中超50天的订单391张），倒冲领料187张，直接领料212张，<span style=\"background-color: rgb(255, 255, 0);\"><font color=\"#ff0000\">已完工未结案订单112张（其中未入库数量为0的88张）</font></span>，请及时</span><span style=\"font-size: 16px; line-height: 1.5; background-color: transparent;\">办理结案</span><span style=\"font-size: 16px; line-height: 1.5; background-color: transparent;\">。</span></div><div style=\"position: static !important;\"><span style=\"font-size: 16px; line-height: 1.5; background-color: transparent;\">&nbsp; &nbsp; &nbsp; 以上，逾期未完成结案的请稽核部协助开成长单处理。</span></div></div></div></div></div></div>\n<div>&nbsp; &nbsp; &nbsp;&nbsp;<img src=\"storage/mail/pjs@kingdisplay.com/cid/Catch(08-26-10-27-57)475425.jpg\" border=\"0\" style=\"font-size: 10.5pt; line-height: 1.5; background-color: transparent;\"></div><div>&nbsp; &nbsp; &nbsp;&nbsp;<img src=\"storage/mail/pjs@kingdisplay.com/cid/Catch8DFE(08-26-10-27-57)119076.jpg\" border=\"0\" style=\"font-size: 10.5pt; line-height: 1.5; background-color: transparent;\"></div><hr style=\"width: 210px; height: 1px;\" color=\"#b5c4df\" size=\"1\" align=\"left\">\n<div><span><div style=\"MARGIN-TOP: 10px; MARGIN-LEFT: 10px; MARGIN-RIGHT: 10px\">\n<div><span style=\"FONT-FAMILY: 宋体; COLOR: #000000; FONT-SIZE: 10.5pt\">\n<div><span>\n<div><span style=\"FONT-FAMILY: 宋体; COLOR: #000000; FONT-SIZE: 10.5pt\">\n<div>\n<div>\n<p style=\"margin: 0px 0cm;\" class=\"MsoNormal\"><span style=\"COLOR: black; FONT-SIZE: 10.5pt\" lang=\"EN-US\"><img style=\"WIDTH: 334px; HEIGHT: 79px\" id=\"_x0000_i1028\" border=\"0\" src=\"storage/mail/pjs@kingdisplay.com/cid/22535_22535_imag(08-26-10-27-57)965885.jpg\" width=\"376\" height=\"146\"></span></p></div>\n<div>\n<p style=\"margin: 0px 0cm;\" class=\"MsoNormal\"><strong><span style=\"FONT-FAMILY: 宋体; COLOR: black; FONT-SIZE: 10.5pt; FONT-WEIGHT: normal\">深圳市国显科技有限公司&nbsp; \n</span></strong></p>\n<p style=\"margin: 0px 0cm;\" class=\"MsoNormal\"><strong><span style=\"FONT-FAMILY: 宋体; COLOR: black; FONT-SIZE: 10.5pt; FONT-WEIGHT: normal\">财务中心 \n谭海园</span></strong></p>\n<p style=\"margin: 0px 0cm;\" class=\"MsoNormal\"><strong><span style=\"FONT-FAMILY: 宋体; COLOR: black; FONT-SIZE: 10.5pt; FONT-WEIGHT: normal\"></span></strong><strong><span style=\"FONT-FAMILY: 宋体; COLOR: black; FONT-SIZE: 10.5pt; FONT-WEIGHT: normal\"></span></strong><span style=\"COLOR: black; FONT-SIZE: 10.5pt\" lang=\"EN-US\"><strong><span style=\"FONT-FAMILY: 宋体; FONT-WEIGHT: normal\">Mobile:13762893531</span></strong></span></p>\n<p style=\"margin: 0px 0cm;\" class=\"MsoNormal\"><span style=\"COLOR: black; FONT-SIZE: 10.5pt\" lang=\"EN-US\"><strong><span style=\"FONT-FAMILY: 宋体; FONT-WEIGHT: normal\"></span></strong></span><span style=\"COLOR: black; FONT-SIZE: 10.5pt\" lang=\"EN-US\"><strong><span style=\"FONT-FAMILY: 宋体; FONT-WEIGHT: normal\"></span></strong></span><span style=\"COLOR: black; FONT-SIZE: 10.5pt\" lang=\"EN-US\"><strong><span style=\"FONT-FAMILY: 宋体; FONT-WEIGHT: normal\"></span></strong></span><span style=\"COLOR: black; FONT-SIZE: 10.5pt\" lang=\"EN-US\"><strong><span style=\"FONT-FAMILY: 宋体; FONT-WEIGHT: normal\"></span></strong></span><strong><span style=\"FONT-FAMILY: 宋体; COLOR: black; FONT-SIZE: 10.5pt; FONT-WEIGHT: normal\" lang=\"EN-US\">Email:tanhaiyuan@kingdisplay.net.cn</span></strong></p>\n<p style=\"margin: 0px 0cm;\" class=\"MsoNormal\"><strong><span style=\"FONT-FAMILY: 宋体; COLOR: black; FONT-SIZE: 10.5pt; FONT-WEIGHT: normal\" lang=\"EN-US\"><span style=\"COLOR: black; FONT-SIZE: 10.5pt\" lang=\"EN-US\"><strong><span style=\"FONT-FAMILY: 宋体; FONT-WEIGHT: normal\">Add:</span></strong></span><strong><span style=\"FONT-FAMILY: 宋体; COLOR: black; FONT-SIZE: 10.5pt; FONT-WEIGHT: normal\">深圳市龙岗区坪地街道坪东社区同富路<span lang=\"EN-US\">9</span>号国显工业园</span></strong><span style=\"COLOR: black; FONT-SIZE: 10.5pt\" lang=\"EN-US\"><br></span></span></strong></p></div></div></span></div></span></div></span></div></div></span></div>\n</body></html>\r\n',NULL,NULL,NULL,NULL,'APcA9wBZB9PQGV-IzWJFNqrm',1,NULL,NULL,1,0,2,'pjs@kingdisplay.com',0,'2019-08-26 15:30:47',NULL,'pop'),(276,'liuanan@kingdisplay.com <liuanan@kingdisplay.com>','pingdi.list <pingdi.list@kingdisplay.com>',NULL,NULL,'2019-08-26 08:57:07','关于手机项目部总监朱乾双出差知会函',NULL,NULL,NULL,NULL,NULL,'AEsAFwCVB1rQozOulOu9hKoN',NULL,NULL,NULL,0,0,3,'pjs@kingdisplay.com',0,'2019-08-26 15:30:47',NULL,'pop'),(276,'阳阳 <yangyang@kingdisplay.com>','pingdi.list <pingdi.list@kingdisplay.net.cn>',NULL,NULL,'2019-08-23 17:13:41','国显科技简介（全行业） 201908 V5.3',NULL,NULL,NULL,NULL,NULL,'AFAAtQDPB9jOXCzdXWyGFaqO',NULL,NULL,NULL,0,0,4,'pjs@kingdisplay.com',0,'2019-08-26 15:30:49',NULL,'pop'),(276,'夏思阳 <xiasiyang@kingdisplay.com>','欧木兰 > <oumulan@kingdisplay.com>,刘涛<liutao@kingdisplay.com>,吴均智<wujunzhi@kingdisplay.com>,边晓丹<bianxiaodan@kingdisplay.com>,徐江峰<xujiangfeng@kingdisplay.com>,黄宽<huangkuan@kingdisplay.com>,寇建斌<koujianbin@kingdisplay.com>,彭军帅<pjs@kingdisplay.com>,熊勤<xiongqin@k',NULL,NULL,'2019-08-23 14:01:29','回复: 关于公司入党积极分子补充材料的相关说明',NULL,NULL,NULL,NULL,NULL,'APYAQQDhB8XNBteQplh1xapp',NULL,NULL,NULL,0,0,5,'pjs@kingdisplay.com',0,'2019-08-26 15:30:50',NULL,'pop'),(276,'liqingyuan@kingdisplay.com <liqingyuan@kingdisplay.com>','吴友丽 <wyl@kingdisplay.com>,pdxinchang.list<pdxinchang.list@kingdisplay.net.cn>,pdzhuguan.list<pdzhuguan.list@kingdisplay.net.cn>,gaoqicheng<gaoqicheng@kingdisplay.com>,dengliting<dengliting@kingdisplay.com>,pingdi.list<pingdi.list@kingdisplay.net.cn>',NULL,NULL,'2019-08-23 09:06:04','2019年8月22日国显稽核日志',NULL,NULL,NULL,NULL,NULL,'AJwARQClBy9NF1-LDSmY4aqZ',NULL,NULL,NULL,0,0,6,'pjs@kingdisplay.com',0,'2019-08-26 15:30:50',NULL,'pop'),(276,'夏思阳 <xiasiyang@kingdisplay.com>','欧木兰 <oumulan@kingdisplay.com>>,刘涛<liutao@kingdisplay.com>,吴均智<wujunzhi@kingdisplay.com>,边晓丹<bianxiaodan@kingdisplay.com>,徐江峰<xujiangfeng@kingdisplay.com>,黄宽<huangkuan@kingdisplay.com>,寇建斌<koujianbin@kingdisplay.com>,彭军帅<pjs@kingdisplay.com>,熊勤<xiongqin@ki','那嘉 <najia@kingdisplay.com>,邵秀锋<shaoxiufeng@kingdisplay.com>',NULL,'2019-08-22 15:16:47','关于公司入党积极分子补充材料的相关说明','<html><head><meta http-equiv=\"content-type\" content=\"text/html; charset=GB2312\"><style>body { line-height: 1.5; }p { margin-top: 0px; margin-bottom: 0px; }body { font-size: 10.5pt; font-family: Tahoma; color: rgb(0, 0, 0); line-height: 1.5; }body { font-size: 10.5pt; font-family: Tahoma; color: rgb(0, 0, 0); line-height: 1.5; }</style></head><body>\n<div><span></span>各位入党积极分子：</div><div>&nbsp; &nbsp; &nbsp;大家好，接到街道“两新”党委的通知，提交入党积极分子的相关资料（手写部分请用黑色签字笔，资料内容见以及相关要求见附件）。<span style=\"line-height: 1.5; font-size: 10.5pt; background-color: transparent;\">请各位入党积极分子尽快做好相关资料，</span><span style=\"font-size: 15px; background-color: transparent;\"><font color=\"#ff0000\"><b>于2019年8月29日前</b></font></span><span style=\"line-height: 1.5; font-size: 10.5pt; background-color: transparent;\">交至人力资源部夏思阳，</span><font color=\"#ff0000\" style=\"line-height: 1.5; font-size: 10.5pt; background-color: transparent;\"><b style=\"font-size: 16px;\">逾期则视为放弃发展入党</b></font><span style=\"line-height: 1.5; font-size: 10.5pt; background-color: transparent;\">。如有疑问请联系人力资源部夏思阳。</span></div><div><br></div><div>祝各位工作顺利，<span style=\"font-size: 10.5pt; line-height: 1.5; background-color: transparent;\">谢谢！</span></div><div><br></div><div>\n<!--StartFragment-->\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"753\" height=\"344\" style=\"border-collapse:collapse;width:564.77pt;\">\n <colgroup><col width=\"40\" style=\"width:30.00pt;\">\n <col width=\"146\" style=\"width:109.50pt;\">\n <col width=\"179\" style=\"width:134.25pt;\">\n <col width=\"388\" style=\"width:291.00pt;\">\n </colgroup><tbody><tr height=\"48\" style=\"height:36.00pt;\">\n  <td colspan=\"4\" class=\"et5\" height=\"48\" width=\"753\" x:str=\"\" style=\"height: 36pt; width: 564.75pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 18pt; font-weight: 700; font-family: 宋体; border: none; border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle; white-space: nowrap; text-align: center;\">入党积极分子所需材料一览表</td>\n </tr>\n <tr height=\"48\" style=\"height:36.00pt;\">\n  <td class=\"et6\" height=\"48\" width=\"40\" x:str=\"\" style=\"height: 36pt; width: 30pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 10pt; font-weight: 700; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle; text-align: center;\">序号</td>\n  <td class=\"et6\" width=\"146\" x:str=\"\" style=\"width: 109.5pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 10pt; font-weight: 700; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle; text-align: center;\">材料名称</td>\n  <td class=\"et7\" width=\"179\" x:str=\"\" style=\"width: 134.25pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 10pt; font-weight: 700; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle; text-align: center;\">“日期”要求</td>\n  <td class=\"et7\" width=\"388\" x:str=\"\" style=\"width: 291pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 10pt; font-weight: 700; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle; text-align: center;\">内容、格式要求</td>\n </tr>\n <tr height=\"66\" style=\"height:50.00pt;\">\n  <td class=\"et8\" height=\"66\" width=\"40\" x:num=\"1\" style=\"height: 50pt; width: 30pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 9pt; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle; text-align: center;\">1</td>\n  <td class=\"et8\" width=\"146\" x:str=\"\" style=\"width: 109.5pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 9pt; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle; text-align: center;\">入党申请书</td>\n  <td class=\"et9\" width=\"179\" x:str=\"\" style=\"width: 134.25pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 9pt; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle;\">1、以花名册上日期为准<br>2、铅笔填写日期</td>\n  <td class=\"et9\" width=\"388\" x:str=\"\" style=\"width: 291pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle;\"><span style=\"font-size: 9pt;\">1、</span><span class=\"font6\" style=\"font-size: 9pt; color: rgb(255, 0, 0); font-weight: 700;\">A4纸手写稿</span><span class=\"font8\" style=\"font-size: 9pt;\"><br>2、内容格式可网查查询<br>3、涉及到理论部分要注意时间点，过去的口吻不能有当年未出现新理论<br>4、个人的经历、心态以当年的口吻写<font color=\"#3366ff\"><br>&nbsp;&nbsp;</font></span><span class=\"font8\" style=\"font-size: 15px;\"><font color=\"#3366ff\">已提交打印稿的可到人力资源部夏思阳处拿回去手写</font></span></td>\n </tr>\n <tr height=\"45\" style=\"height:34.00pt;\">\n  <td class=\"et8\" height=\"45\" width=\"40\" x:num=\"2\" style=\"height: 34pt; width: 30pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 9pt; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle; text-align: center;\">2</td>\n  <td class=\"et8\" width=\"146\" x:str=\"\" style=\"width: 109.5pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 9pt; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle; text-align: center;\">要求入党积极分子<br>登记表</td>\n  <td class=\"et9\" width=\"179\" x:str=\"\" style=\"width: 134.25pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 9pt; font-family: 宋体; border: 0.5pt solid rgb(0, 0, 0); border-image-source: initial; border-image-slice: initial; border-image-width: initial; border-image-outset: initial; border-image-repeat: initial; vertical-align: middle;\">1、以花名册上日期为准<br>2、铅笔填写日期</td>\n  <td class=\"et10\" width=\"388\" x:str=\"\" style=\"width: 291pt; padding-top: 1px; padding-left: 1px; padding-right: 1px; font-size: 9pt; font-family: 宋体; border: 0.5pt 