  `parenttab_label` varchar(255) DEFAULT NULL COMMENT '区间名称',
  `allocatetype` varchar(255) DEFAULT NULL COMMENT '可见范围类型',
  `allocateid` varchar(255) DEFAULT NULL COMMENT '可见范围',
  `enblock_name` varchar(255) DEFAULT NULL,
