/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `update_by_outboundorder1` BEFORE UPDATE ON `ld_outboundorder` FOR EACH ROW BEGIN

IF @disable_triggers IS NULL THEN
 

	set new.receivable_balance=round(ifnull(new.total,0)-ifnull(new.received_amount,0),2);
	
END IF;

END */;;
