/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `reset_account_outboundorder_qty` AFTER UPDATE ON `ld_outboundorder` FOR EACH ROW BEGIN

IF @disable_triggers IS NULL THEN
 

	IF NEW.accountid>0 THEN
		UPDATE ld_account SET outboundorder_qty=(SELECT COUNT(1) FROM ld_outboundorder WHERE deleted=0 AND accountid=NEW.accountid) WHERE accountid=NEW.accountid;
	END IF;

	IF OLD.accountid>0 AND OLD.accountid<>IFNULL(NEW.accountid,0) THEN
		UPDATE ld_account SET outboundorder_qty=(SELECT COUNT(1) FROM ld_outboundorder WHERE deleted=0 AND accountid=OLD.accountid) WHERE accountid=OLD.accountid;
	END IF;

END IF;

END */;;
DELIMITER ;
