--
-- Table structure for table `ld_paymentplan`
--

DROP TABLE IF EXISTS `ld_paymentplan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_paymentplan` (
  `paymentplanid` int(11) NOT NULL,
  `paymentplan_no` varchar(100) DEFAULT NULL,
  `accountid` int(19) DEFAULT NULL,
  `salesorderid` int(19) DEFAULT NULL,
  `Periodtime` varchar(50) DEFAULT NULL,
  `plandate` date DEFAULT NULL,
  `actualdate` date DEFAULT NULL,
  `amount` decimal(25,8) DEFAULT NULL,
  `actualamount` decimal(25,8) DEFAULT NULL,
  `paymentstatus` varchar(255) DEFAULT NULL,
  `smownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `deleted` int(11) DEFAULT '0',
  `description` text,
  `projectstatus` varchar(100) DEFAULT NULL,
  `entitytypeid` int(11) DEFAULT '0',
  `entitytype` varchar(100) DEFAULT NULL,
  `currency_id` int(1) DEFAULT '1',
  `conversion_rate` decimal(25,6) DEFAULT '1.000000',
  `currency_symbol` varchar(30) DEFAULT '¥',
  `receivable_balance` decimal(25,8) DEFAULT NULL,
  `print_times` int(11) DEFAULT '0',
  `paymenttype` varchar(100) DEFAULT NULL,
  `approvetime` datetime DEFAULT NULL,
  `approvestatus` varchar(100) DEFAULT '未提交',
  `currentapprover` varchar(1000) DEFAULT NULL,
  `approveby` int(19) DEFAULT '0',
  `advance_stage` varchar(100) DEFAULT NULL,
  `approvesubmitter` int(19) DEFAULT '0',
  `approvesubmittedtime` datetime DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT 'no',
  `approveexpediting` varchar(10) DEFAULT 'no',
  `currentapprovestepid` int(19) DEFAULT '0',
  `team_memberid` text,
  `tag` varchar(50) DEFAULT NULL,
  `kis_id` varchar(200) DEFAULT NULL,
  `kis_no` varchar(200) DEFAULT NULL,
  `exchtime` datetime DEFAULT NULL,
  `exchmsg` text,
  `latestpushtime` datetime DEFAULT NULL,
  `projectid` int(19) DEFAULT '0',
  PRIMARY KEY (`paymentplanid`),
  KEY `idx_ld_paymentstatus` (`paymentstatus`) USING BTREE,
  KEY `idx_lD_plandate` (`plandate`) USING BTREE,
  KEY `idx_lD_accountid` (`accountid`) USING BTREE,
  KEY `accountid` (`accountid`),
  KEY `approvestatus` (`approvestatus`),
  KEY `createdtime` (`createdtime`),
  KEY `modifiedtime` (`modifiedtime`),
  KEY `smcreatorid` (`smcreatorid`),
  KEY `smownerid` (`smownerid`),
  CONSTRAINT `ld_paymentplan_ibfk_1` FOREIGN KEY (`paymentplanid`) REFERENCES `ld_crmentity` (`crmid`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
