  `modulename` varchar(100) NOT NULL COMMENT '模块名称',
  `record` int(19) NOT NULL COMMENT '存单据id 加索引',
  `total` decimal(15,2) NOT NULL COMMENT '总金额',
  `currency` char(5) NOT NULL DEFAULT 'CNY' COMMENT '币种，默认CNY，境内商户只允许CNY',
