INSERT INTO `ld_workflow_excutesql` VALUES (5,5,'UPDATE ld_collectionslip a\r\nINNER JOIN ld_account b ON b.accountname=a.remit_account_name\r\nSET \r\na.accountid=b.accountid,\r\na.smownerid=b.smownerid\r\nWHERE a.collectionslip_id=\'{Record.ID}\'\r\nAND b.deleted=0\r\nAND IFNULL(a.accountid,0)  = 0;'),(6,6,'CALL autocreatecashbillbycollectionsslip_where(\'{Record.ID}\');');
