INSERT INTO `ld_workreport` VALUES (2,'2021-06-21 11:40:07','完善客户石松项目调查报告，出具反担保清单，盖章交银行。整理客户流程表，梳理客户操作流畅。跟进银行客户进度情况，更新客户进度表。制定客户周再银，个人资产证明。传真银行。方利群客户石松交接工作，客户石松申请表格盖章。','','',1,1,0,0,NULL,NULL,0,NULL,NULL,'workreport','','','','','','','','2021-06-21','','','','WRPT1',0,252,NULL,NULL,'374,390,375,391,376,392,377,393,378,394,379,395,380,381,382,383,384,385,1,386,371,387,372,388,373,389','否',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(3,'2024-08-07 13:32:05','请生成简报完善客户石松项目调查报告，出具反担保清单，盖章交银行。整理客户流程表，梳理客户操作流畅。跟进银行客户进度情况，更新客户进度表。制定客户周再银，个人资产证明。传真银行。方利群客户石松交接工作，客户石松申请表格盖章。','','',1,1,0,0,NULL,NULL,0,NULL,NULL,'workreport','','','','','','','','2024-08-07','','','','WRPT2',0,1,NULL,NULL,'1,371,372,373,374,375,376,377,378,379,380,381,382,383,384,385,386,387,388,389,390,391,392,393,394,395','否','','','',NULL,NULL,NULL,NULL,NULL,NULL,0),(4,'2024-08-07 13:32:30','我完成了一项非常重要的项目。这个项目是我们团队共同努力的成果，我感到非常自豪和满意。在项目中，我主要负责了需求分析和项目管理方面的工作，协调了各个团队成员之间的工作，保证了项目的顺利进行和按时完成。在这个项目中，我学到了很多关于团队合作、项目管理、沟通协调等方面的技巧和经验，这些都是我未来工作中需要不断提升和发挥的能力。','','',1,1,0,0,NULL,NULL,0,NULL,NULL,'workreport','','','','','','','','2024-08-07','','','','WRPT3',0,1,NULL,NULL,'1,371,372,373,374,375,376,377,378,379,380,381,382,383,384,385,386,387,388,389,390,391,392,393,394,395','否','','','',NULL,NULL,NULL,NULL,NULL,NULL,0),(5,'2024-08-07 13:32:47','除此之外，我还参加了一个重要的会议，了解了一些新的业务领域和市场趋势。这些信息对我未来的工作非常有帮助，可以帮助我更好地为公司做出贡献。在会议中，我也与一些新的客户和合作伙伴进行了交流，了解了他们对我们产品的看法和建议，这对我们产品的改进和创新非常重要。','','',1,1,0,0,NULL,NULL,0,NULL,NULL,'workreport','','','','','','','','2024-08-07','','','','WRPT4',0,1,NULL,NULL,'1,371,372,373,374,375,376,377,378,379,380,381,382,383,384,385,386,387,388,389,390,391,392,393,394,395','否','','','',NULL,NULL,NULL,NULL,NULL,NULL,0);
/*!40000 ALTER TABLE `ld_workreport` ENABLE KEYS */;
UNLOCK TABLES;

