INSERT INTO `ld_workreport_remind` VALUES ('workreport',2,1,2,1,'2021-06-21 11:40:07','系统管理员发出日志:完善客户石松项目调查报告，出具反担保清单，盖章交银行。整理客户流程表，梳理客户操作流畅。跟进银行客户进度情况，更新客户进度表。制定客户周再银，个人资产证明。传真银行。方利群客户石松交接工作，客户石松申请表格盖章。',0,4,3,2,'2021-06-21 11:40:07',NULL,2,NULL,0,NULL,3,NULL,3,NULL,0,NULL),('praise',3,6,20,1,'2022-07-26 09:02:30','系统管理员赞了我的工作',0,6,2,2,NULL,NULL,2,NULL,2,NULL,3,NULL,3,NULL,0,NULL),('praise',4,6,NULL,1,'2022-07-26 09:03:14','系统管理员赞了我的工作',0,6,2,2,NULL,NULL,2,NULL,2,NULL,3,NULL,3,NULL,0,NULL),('workreport',5,1,3,1,'2024-08-07 13:32:05','系统管理员发出日志:请生成简报完善客户石松项目调查报告，出具反担保清单，盖章交银行。整理客户流程表，梳理客户操作流畅。跟进银行客户进度情况，更新客户进度表。制定客户周再银，个人资产证明。传真银行。方利群客户石松交接工作，客户石松申请表格盖章。',0,4,2,2,NULL,NULL,2,NULL,2,NULL,2,NULL,2,NULL,0,NULL),('workreport',6,1,4,1,'2024-08-07 13:32:30','系统管理员发出日志:我完成了一项非常重要的项目。这个项目是我们团队共同努力的成果，我感到非常自豪和满意。在项目中，我主要负责了需求分析和项目管理方面的工作，协调了各个团队成员之间的工作，保证了项目的顺利进行和按时完成。在这个项目中，我学到了很多关于团队合作、项目管理、沟通协调等方面的技巧和经验，这些都是我未来工作中需要不断提升和发挥的能力。',0,4,2,2,NULL,NULL,2,NULL,2,NULL,2,NULL,2,NULL,0,NULL),('workreport',7,1,5,1,'2024-08-07 13:32:47','系统管理员发出日志:除此之外，我还参加了一个重要的会议，了解了一些新的业务领域和市场趋势。这些信息对我未来的工作非常有帮助，可以帮助我更好地为公司做出贡献。在会议中，我也与一些新的客户和合作伙伴进行了交流，了解了他们对我们产品的看法和建议，这对我们产品的改进和创新非常重要。',0,4,2,2,NULL,NULL,2,NULL,2,NULL,2,NULL,2,NULL,0,NULL);
/*!40000 ALTER TABLE `ld_workreport_remind` ENABLE KEYS */;
UNLOCK TABLES;

