DELIMITER ;;
CREATE  FUNCTION `func_changeToHalfAngle`(in_str TEXT) RETURNS text CHARSET utf8
BEGIN  

	DECLARE out_str TEXT;

	
	SET in_str=REPLACE(in_str,'，',',');
	SET in_str=REPLACE(in_str,'＜','<');

	SET in_str=REPLACE(in_str,'．','.');
	SET in_str=REPLACE(in_str,'＞','>');

	SET in_str=REPLACE(in_str,'／','/');
	SET in_str=REPLACE(in_str,'？','?');

	SET in_str=REPLACE(in_str,'：',':');
