									'Integration',
									'Mobile',
									'PBXManager',
									'Services',
									'lingdangBackup',
									'WSAPP',
									'Assets',
									'CronTasks',
									'SMSNotifier',
									'Webforms',
									'Announcements',
									'MassFaxs',
									'MassVoices',
									'mobileAccounts',
									'mobileContacts',
									'mobileContactRecords',
									'mobileSalesOrder',
									'GraphicalReports',
									'mobileProducts',
									'mobilePublicAnnouncement',
									'mobileHelpDesk',
									'CustomerPortal'
								);
					end if;
					FETCH psetuserscoperresult INTO puserid,pscopeauthority;
				END WHILE LOOP1;
			CLOSE psetuserscoperresult;
	END IF;
END ;;
