DELIMITER ;;
CREATE  PROCEDURE `ldcrm_drop_producttoolfield_20190722`(
)
BEGIN

	DECLARE tmp_tabid INT(19) DEFAULT 0;
	DECLARE tmp_productfieldid INT(19) DEFAULT 0;
	DECLARE tmp_columnname VARCHAR(100) DEFAULT ''; 
	DECLARE tmp_tablename VARCHAR(100) DEFAULT ''; 

	DECLARE MYCUSOR CURSOR FOR 
									SELECT
										tabid,
										producttoolfieldid,
										columnname,
										tablename
									FROM ld_producttoolfield
									WHERE columnname NOT IN ('sf3','sendarea','expiry_date')
										AND tablename LIKE '%detailscf'
									ORDER BY tabid,sequence;
	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_tabid = NULL;

	OPEN MYCUSOR; 
	FETCH MYCUSOR INTO tmp_tabid,tmp_productfieldid,tmp_columnname,tmp_tablename;
	WHILE(tmp_productfieldid IS NOT NULL) DO
		DELETE FROM ld_tranlabel WHERE trantable='ld_producttoolfield' AND tabid=tmp_tabid AND Relateid=tmp_productfieldid;
		DELETE FROM ld_producttoolfield WHERE producttoolfieldid=tmp_productfieldid;
		CALL DelColumn(tmp_tablename,tmp_columnname);
		FETCH MYCUSOR INTO tmp_tabid,tmp_productfieldid,tmp_columnname,tmp_tablename;
	END WHILE;
	CLOSE MYCUSOR;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_drop_producttoolfield_2019072202` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_drop_producttoolfield_2019072202`(
)
BEGIN


	DECLARE tmp_columnname VARCHAR(100) DEFAULT ''; 
	DECLARE tmp_tablename VARCHAR(100) DEFAULT ''; 

	DECLARE MYCUSOR CURSOR FOR 
						SELECT
							COLUMN_NAME,
							TABLE_NAME
						FROM information_schema.COLUMNS 
						WHERE TABLE_SCHEMA=DATABASE() 
							AND TABLE_NAME IN (SELECT tablename FROM ld_producttoolfield WHERE tablename LIKE '%detailscf' GROUP BY tablename)
							AND COLUMN_NAME NOT IN ('lineitem_id','sendarea','sf3','sequence','expiry_date','pro_id')
						ORDER BY COLUMN_NAME,TABLE_NAME;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_columnname = NULL;

	OPEN MYCUSOR; 
	FETCH MYCUSOR INTO tmp_columnname,tmp_tablename;
	WHILE(tmp_columnname IS NOT NULL) DO
		CALL DelColumn(tmp_tablename,tmp_columnname);
		FETCH MYCUSOR INTO tmp_columnname,tmp_tablename;
	END WHILE;
	CLOSE MYCUSOR;

end ;;
DELIMITER ;
