CREATE  PROCEDURE `leads_singlerecycle_normal_rule_beforeremind`(new_normal_id 	int(11),new_pool_id 	int(11))
label_a:BEGIN

	DECLARE var_tabname varchar(100);
	DECLARE var_columnname varchar(100);
	DECLARE var_tablename varchar(100);
	DECLARE var_condition varchar(50);
	DECLARE var_smownercolumn varchar(50);
	declare var_leadsidcolumnname varchar(100);
	declare var_iscycle varchar(50);
	DECLARE var_days int(11);
	DECLARE var_otherwhere varchar(200);
	declare done  int  default 0;

	declare cur1 CURSOR FOR select tabname,ld_leads_set_rule.columnname,ld_field.tablename ,
                                   ld_leads_set_rule.iscycle,`condition`,ld_leads_set_rule.days
                                                                                                                                                                        ,ld_leads_set_rule.otherwhere from ld_leads_set_rule  inner join ld_tab on ld_tab.name=ld_leads_set_rule.tabname and (presence in(0,2) or ld_leads_set_rule.tabname='singin')
                                                                                                                                                                                                                              INNER JOIN ld_field on ld_field.tabid=ld_tab.tabid and ld_leads_set_rule.columnname=ld_field.columnname
    and ld_field.presence in(0,2) where ld_leads_set_rule.type='normal' and ld_leads_set_rule.`status`='active' and programmeid = new_normal_id;

declare continue handler  for not   found  SET done =1;

    IF EXISTS (SELECT 1 FROM ld_leads_public WHERE show_account_rule='yes') THEN
    	set @tmpint=0;
    	set @tmpsql='';
	select max(ld_leads_set_rule.days) into @maxdays
	from ld_leads_set_rule  inner join ld_tab on ld_tab.name=ld_leads_set_rule.tabname and (presence in(0,2) or ld_leads_set_rule.tabname='singin')
                        INNER JOIN ld_field on ld_field.tabid=ld_tab.tabid and ld_leads_set_rule.columnname=ld_field.columnname
    and ld_field.presence in(0,2) where ld_leads_set_rule.type='normal' and ld_leads_set_rule.`status`='active' and programmeid = new_normal_id;
		
		set @leads_rule_pool_id = new_pool_id;
		select recycleselect,beforereminddays into @recycleselect,@var_beforereminddays from ld_leads_normal where id = new_normal_id;

		if @var_beforereminddays='' or @var_beforereminddays is null or @var_beforereminddays=0 then
						leave label_a ;
		end if;
       set @maxdays=@maxdays-@var_beforereminddays;

    	if @recycleselect is not null and @recycleselect<>'' then
    			set @recycleselect=concat( '( ', @recycleselect,' ) as recyclewheretableset ');
end if;
OPEN cur1;

Fetch cur1 into var_tabname,var_columnname,var_tablename,var_iscycle,var_condition,var_days,var_otherwhere;
loop1: while  done<>1 DO

    			if var_tablename='ld_singin' THEN
    					set var_smownercolumn='userid';
						  set	var_leadsidcolumnname='record' ;
else
    				set	var_smownercolumn='smownerid' ;
					   set	var_leadsidcolumnname='leads_id' ;
end if;
    			 set var_days=var_days-@var_beforereminddays;
    			if var_days<=0 THEN
    				leave loop1;
end if;
    		  if(var_condition='and' ) then

    			set @tmpsqlone =concat("select ld_leads.leadsid,ld_leads.distributiondate,ld_leads.createdtime, '",var_tabname,"' as remindtabname from ld_leads ");
    			set @tmpsqlone=concat(@tmpsqlone," inner join ",var_tablename,' on ',var_tablename,'.',var_leadsidcolumnname,'=ld_leads.leadsid' );
    			set @tmpsqltwo=concat(@tmpsqltwo," and  ",var_tablename,'.',var_smownercolumn,'=ld_leads.smownerid ');

    			 set @tmpsqlone=concat(@tmpsqlone," where   ",var_tablename,".deleted=0  ");
    		   if var_otherwhere is not null and  var_otherwhere<>'' then
    					set @tmpsqlone=concat(@tmpsqlone,var_otherwhere);
end if;

    		  if var_iscycle ='yes' then
    				 set @tmpsqlone=concat( @tmpsqlone,' group by ld_leads.leadsid ') ;
    				set @tmpsqlone=concat(@tmpsqlone,"   having    datediff(curdate(),case when   IF(IFNULL(ld_leads.distributiondate,'0000-00-00')<='1600-00-00',ld_leads.createdtime,ld_leads.distributiondate)>    max(",var_tablename,'.',var_columnname,") then  IF(IFNULL(ld_leads.distributiondate,'0000-00-00')<='1600-00-00',ld_leads.createdtime,ld_leads.distributiondate)  else max(",var_tablename,'.',var_columnname,") end  ) >",var_days   );
else
    				set @tmpsqlone=concat(@tmpsqlone," and IF(IFNULL(ld_leads.distributiondate,'0000-00-00')<='1600-00-00',ld_leads.createdtime,ld_leads.distributiondate)<=",var_tablename,'.',var_columnname);
    				 set @tmpsqlone=concat( @tmpsqlone,' group by ld_leads.leadsid ') ;
    				set @tmpsqlone=concat(@tmpsqlone,"  having datediff(min( ",var_tablename,'.',var_columnname,"),IF(IFNULL(ld_leads.distributiondate,'0000-00-00')<='1600-00-00',ld_leads.createdtime,ld_leads.distributiondate))>",var_days);

end if;

               set @tmpsqltwo=concat("select ld_leads.leadsid,ld_leads.distributiondate,ld_leads.createdtime , '",var_tabname,"' as remindtabname from ld_leads LEFT JOIN (select ld_leads.leadsid from ld_leads inner join ",var_tablename,' on ld_leads.leadsid=',
                    var_tablename,'.leadsid and ld_leads.smownerid=',var_tablename,'.',var_smownercolumn,'  where ',var_tablename,'.deleted=0');

    		   if var_otherwhere is not null and  var_otherwhere<>'' then
    					set @tmpsqltwo=concat(@tmpsqltwo, var_otherwhere);
end if;
    			set @tmpsqltwo=concat(@tmpsqltwo,' ) 	as ttt_',var_tablename,'  on ld_leads.leadsid=ttt_',var_tablename,'.leads_id   where ttt_',var_tablename,'.leads_id is null  ' );
    			set @tmpsqltwo=concat(@tmpsqltwo," having datediff(curdate(),IF(IFNULL(ld_leads.distributiondate,'0000-00-00')<='1600-00-00',ld_leads.createdtime,ld_leads.distributiondate) ) >",var_days);


    			set @tmpthree=concat( @tmpsqlone,' union all ',@tmpsqltwo);
    			set @tmpsql=concat(@tmpsql," select * from ( ",@tmpthree," ) as  tttt_",var_tabname);
    			set @tmpsql=concat(@tmpsql,' union all ' );

    			elseif (var_condition='or')  then
    				set @tmpsql=concat(@tmpsql ," select ld_leads.leadsid,ld_leads.distributiondate,ld_leads.createdtime, '",var_tabname,"' as remindtabname from ld_leads inner join "  ,var_tablename,' on ',var_tablename,'.',var_leadsidcolumnname,'=ld_leads.leadsid  ');
    			  set @tmpsql=concat(@tmpsql,' and ' ,var_tablename,'.',var_smownercolumn,'=ld_leads.smownerid ' );
    				set @tmpsql=concat(@tmpsql,' where  ' , var_tablename,'.deleted=0 ' );
    				if var_otherwhere is not null and  var_otherwhere<>'' then
    					set @tmpsql=concat(@tmpsql,var_otherwhere);
end if;

    				if var_iscycle='yes' then
    					set @tmpsql=concat(@tmpsql," group by ld_leads.leadsid ");
    						set @tmpsql=concat(@tmpsql," having datediff(curdate(), case when  IF(IFNULL(ld_leads.distributiondate,'0000-00-00')<='1600-00-00',ld_leads.createdtime,ld_leads.distributiondate)>max( ", var_tablename,'.',var_columnname,") then  IF(IFNULL(ld_leads.distributiondate,'0000-00-00')<='1600-00-00',ld_leads.createdtime,ld_leads.distributiondate)   else  max( ", var_tablename,'.',var_columnname,") end )<= ",var_days);
else
    						set @tmpsqlone=concat(@tmpsql," and IF(IFNULL(ld_leads.distributiondate,'0000-00-00')<='1600-00-00',ld_leads.createdtime,ld_leads.distributiondate)<=",var_tablename,'.',var_columnname);
    						set @tmpsql=concat(@tmpsql," group by ld_leads.leadsid ");
    						set @tmpsqlone=concat(@tmpsql,"  having datediff(min( ",var_tablename,'.',var_columnname,"),IF(IFNULL(ld_leads.distributiondate,'0000-00-00')<='1600-00-00',ld_leads.createdtime,ld_leads.distributiondate))<=",var_days);
end if;

    				set @tmpsql=concat(@tmpsql,' union all ' );

end if;
    			set @tmpint=@tmpint+1;
Fetch cur1 into var_tabname,var_columnname,var_tablename,var_iscycle, var_condition,var_days,var_otherwhere;
end while loop1;
close cur1;


if @tmpint>0 then
    			set @len=CHAR_LENGTH(' union all ');
    			set @tmpsql=left(@tmpsql,CHAR_LENGTH(@tmpsql)-@len);

    			if var_condition='or'  then
    				 set @TMP_TMPTable= ( select  concat('"(',GROUP_CONCAT(ld_tranlabel.fieldlabel),')"')  from ld_leads_set_rule
    									INNER JOIN ld_tab on ld_tab.name=ld_leads_set_rule.tabname
    									INNER JOIN ld_tranlabel on ld_tab.tabid=ld_tranlabel.tabid
    									and ld_tab.tabid=ld_tranlabel.Relateid and languagetype='zh' and trantable='ld_tab'
    										where type='complete' and ld_leads_set_rule.status='active' and ld_leads_set_rule.status='active' and programmeid = new_normal_id ORDER BY ld_leads_set_rule.sequence asc ) ;
						
						set @tmp_namelink=concat('\'<a style="display: initial;" doubleclick="yes" onclick="ListReferenceLinkClick(ld(this),event)" referencemodule="Leads" referencerecord="\',ld_leads.leadsid,\'">\',ld_leads.accountname,',@TMP_TMPTable,',\'</a>\'');
    				set @sql=concat(' select leadsid from (',@tmpsql, ') as tmpone group by leadsid ') ;

    				set @TMPSQL_ONE=concat( ' select "normal", group_concat(',@tmp_namelink,' separator "<br>" )  as accouontnames ,count(distinct ld_leads.leadsid)  as totalleadss,ld_leads.smownerid from ld_leads left join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid ') ;
    				if @recycleselect<>'' and @recycleselect is not null THEN
    					set @TMPSQL_ONE=concat(@TMPSQL_ONE,' left join ',@recycleselect,' on recyclewheretableset.leadsid=ld_leads.leadsid ');
end if;
    				 set @TMPSQL_TWO=concat(@TMPSQL_ONE,' where ld_leads.deleted=0 and( ifnull(ld_leads.publicaccount,0)<1)');
    					set @TMPSQL_TWO=concat(@TMPSQL_TWO, " and lingdangtmp.leadsid is null  and datediff(curdate(),case when ifnull(ld_leads.distributiondate,'')='' then ld_leads.createdtime else ld_leads.distributiondate end)>",@maxdays);
    					if @recycleselect<>'' and @recycleselect is not null THEN
    						set @TMPSQL_TWO=concat(@TMPSQL_TWO, ' and recyclewheretableset.leadsid is not null ');
end if;
    				 set @TMPSQL_TWO=concat(@TMPSQL_TWO," group by ld_leads.smownerid ");

else
    				if @recycleselect is not null and @recycleselect<>'' then

    					set @sql=concat(' select tmpone.leadsid,GROUP_CONCAT(ld_tranlabel.fieldlabel) as fieldlabel from  (',@tmpsql, ' ) as tmpone
    												inner join ',@recycleselect,' on tmpone.leadsid=recyclewheretableset.leadsid
    												inner join ld_tab on ld_tab.name=tmpone.remindtabname
    										 	INNER JOIN ld_tranlabel on ld_tab.tabid=ld_tranlabel.tabid
    										  and ld_tab.tabid=ld_tranlabel.Relateid and languagetype="zh" and trantable="ld_tab"
    											 group by leadsid ') ;
ELSE
    					set @sql=concat(' select leadsid,GROUP_CONCAT(ld_tranlabel.fieldlabel) as fieldlabel from (',@tmpsql, ') as tmpone
    											inner join ld_tab on ld_tab.name=tmpone.remindtabname
    											INNER JOIN ld_tranlabel on ld_tab.tabid=ld_tranlabel.tabid
    										  and ld_tab.tabid=ld_tranlabel.Relateid and languagetype="zh" and trantable="ld_tab"
    											 group by leadsid') ;
end if;
						set @tmp_namelink=concat('\'<a style="display: initial;" doubleclick="yes" onclick="ListReferenceLinkClick(ld(this),event)" referencemodule="Leads" referencerecord="\',ld_leads.leadsid,\'">\',ld_leads.accountname,lingdangtmp.fieldlabel,\'</a>\'');
    				set @TMPSQL_ONE=concat( ' select "normal",  GROUP_CONCAT(',@tmp_namelink,' separator "<br>")as accountname,count(distinct ld_leads.leadsid)  as totalleadss,ld_leads.smownerid from    ld_leads  inner join ( ',@sql,' ) as lingdangtmp  on  lingdangtmp.leadsid=ld_leads.leadsid ') ;
    				set @TMPSQL_TWO=concat(@TMPSQL_ONE,' where ld_leads.deleted=0 and( ifnull(ld_leads.publicaccount,0)<1) group by ld_leads.smownerid'  );
end if;

delete from ld_publicleads_remindtableview ;

set @tmpthree=concat(" insert into ld_publicleads_remindtableview(type,names,totalleads,smownerid )  ", @TMPSQL_TWO);
prepare stmt from @tmpthree;
execute stmt;
deallocate prepare stmt;

call crm_publicleads_beforereminds();
end if;
END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `lingdang_reset_demodb_everyday` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `lingdang_reset_demodb_everyday`(
)
BEGIN

	
	SET @disable_triggers=1;

	
	
	SET @record_step=(SELECT CEIL(COUNT(1)/80) FROM ld_account WHERE deleted=0);
	IF @record_step<2 THEN
		SET @record_step=2;
	END IF;

	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_account WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(accountid) FROM (SELECT accountid FROM ld_account WHERE deleted=0 ORDER BY accountid DESC LIMIT ",ROUND(@j*@record_step),',',@record_step,") t )");
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_account SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(accountid,@mycrmid) ORDER BY accountid DESC;
		SET @j=@j+1+@record_step;
		
	END WHILE;
	
	UPDATE ld_account set nolinkdays=datediff(CURDATE(),ifnull(lastcontactdate,date_format(createdtime,'%Y-%m-%d')));

	
	
	SET @record_step=(SELECT CEIL(COUNT(1)/80) FROM ld_contactrecords WHERE deleted=0);
	IF @record_step<2 THEN
		SET @record_step=2;
	END IF;

	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_contactdetails WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(contactid) FROM (SELECT contactid FROM ld_contactdetails WHERE deleted=0 ORDER BY contactid DESC LIMIT ",ROUND(@j*@record_step),',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_contactdetails SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(contactid,@mycrmid) ORDER BY contactid DESC;
		SET @j=@j+1+@record_step;
	END WHILE;

	
	
	SET @record_step=(SELECT CEIL(COUNT(1)/80) FROM ld_contactrecords WHERE deleted=0);
	IF @record_step<5 THEN
		SET @record_step=5;
	END IF;

	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_contactrecords WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(contactrecordID) FROM (SELECT contactrecordID FROM ld_contactrecords WHERE deleted=0 ORDER BY contactrecordID DESC LIMIT ",ROUND(@j*@record_step),',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_contactrecords SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(contactrecordID,@mycrmid) ORDER BY contactrecordID DESC;
		SET @j=@j+1+@record_step;
	END WHILE;
	UPDATE ld_contactrecords SET contactdate=DATE_ADD(createdtime,INTERVAL 5 HOUR);
	UPDATE ld_contactrecords SET nextContactDate=DATE_ADD(contactdate,INTERVAL 3 DAY);

	
	
	SET @record_step=(SELECT CEIL(COUNT(1)/80) FROM ld_salesorder WHERE deleted=0);
	IF @record_step<3 THEN
		SET @record_step=3;
	END IF;

	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_salesorder WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(salesorderid) FROM (SELECT salesorderid FROM ld_salesorder WHERE deleted=0 ORDER BY salesorderid DESC LIMIT ",ROUND(@j*@record_step),',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_salesorder SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(salesorderid,@mycrmid) ORDER BY salesorderid DESC;
		SET @j=@j+1+@record_step;
	END WHILE;
	UPDATE ld_salesorder SET signed_data=DATE_FORMAT(createdtime,'%Y_%m-%d');


	
	
	SET @record_step=(SELECT CEIL(COUNT(1)/80) FROM ld_servicecontracts WHERE deleted=0);
	IF @record_step<3 THEN
		SET @record_step=3;
	END IF;

	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_servicecontracts WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(servicecontractsid) FROM (SELECT servicecontractsid FROM ld_servicecontracts WHERE deleted=0 ORDER BY servicecontractsid DESC LIMIT ",ROUND(@j*@record_step),',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_servicecontracts SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(servicecontractsid,@mycrmid) ORDER BY servicecontractsid DESC;
		SET @j=@j+1+@record_step;
	END WHILE;

	UPDATE ld_servicecontracts SET due_date=DATE_FORMAT(createdtime,'%Y_%m-%d');

	UPDATE ld_servicecontracts a
	LEFT JOIN ld_servicecontractsdetail b On b.id=a.servicecontractsid
	SET b.servicecontracts_start_date=a.due_date,b.servicecontracts_end_date=DATE_SUB(DATE_ADD(a.due_date,INTERVAL 1 YEAR),INTERVAL 1 DAY);

	DELETE FROM ld_maxservicedate;
	INSERT INTO ld_maxservicedate(inventoryid,productid,accountid,service_enddate)
	SELECT
		id,
		productid,
		accountid,
		MAX(servicecontracts_end_date) AS servicecontracts_end_date
	FROM (
		SELECT
			b.id,
			b.productid,
			a.accountid,
			b.servicecontracts_end_date
		FROM ld_servicecontracts a
		LEFT JOIN ld_servicecontractsdetail b ON b.id=a.servicecontractsid
		WHERE a.deleted=0
			AND a.approvestatus<>'已拒绝'
		ORDER BY a.accountid,b.productid,b.servicecontracts_end_date DESC
	) tmp
	GROUP BY accountid,productid
	ORDER BY accountid,productid;


	
	
	SET @record_step=(SELECT CEIL(COUNT(1)/80) FROM ld_potential WHERE deleted=0);
	IF @record_step<2 THEN
		SET @record_step=2;
	END IF;

	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_potential WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(potentialid) FROM (SELECT potentialid FROM ld_potential WHERE deleted=0 ORDER BY potentialid DESC LIMIT ",ROUND(@j*@record_step),',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_potential SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(potentialid,@mycrmid) ORDER BY potentialid DESC;
		SET @j=@j+1+@record_step;
	END WHILE;

	UPDATE ld_potential SET closingdate=DATE_ADD(DATE_FORMAT(createdtime,'%Y_%m-%d'),INTERVAL 20 DAY);


	
	
	SET @record_step=(SELECT CEIL(COUNT(1)/80) FROM ld_invoice WHERE deleted=0);
	IF @record_step<2 THEN
		SET @record_step=2;
	END IF;

	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_invoice WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(id) FROM (SELECT invoiceid AS id FROM ld_invoice WHERE deleted=0 ORDER BY id DESC LIMIT ",ROUND(@j*@record_step),',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_invoice SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(invoiceid,@mycrmid) ORDER BY invoiceid DESC;
		SET @j=@j+1+@record_step;
	END WHILE;

	UPDATE ld_invoice SET invoicedate=DATE_FORMAT(createdtime,'%Y_%m-%d');


	
	
	SET @record_step=(SELECT CEIL(COUNT(1)/80) FROM ld_cashbill WHERE deleted=0);
	IF @record_step<2 THEN
		SET @record_step=4;
	END IF;

	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_cashbill WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(id) FROM (SELECT cashbillid AS id FROM ld_cashbill WHERE deleted=0 ORDER BY id DESC LIMIT ",ROUND(@j*@record_step),',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_cashbill SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime,cashbilldate=DATE_FORMAT(createdtime,'%Y_%m-%d') WHERE FIND_IN_SET(cashbillid,@mycrmid) ORDER BY cashbillid DESC;
		SET @j=@j+1+@record_step;
	END WHILE;


	
	
	SET @record_step=(SELECT CEIL(COUNT(1)/80) FROM ld_outboundorder WHERE deleted=0);
	IF @record_step<4 THEN
		SET @record_step=4;
	END IF;

	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_outboundorder WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(id) FROM (SELECT out_id AS id FROM ld_outboundorder WHERE deleted=0 ORDER BY id DESC LIMIT ",ROUND(@j*@record_step),',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_outboundorder SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime,outdate=DATE_FORMAT(createdtime,'%Y_%m-%d') WHERE FIND_IN_SET(out_id,@mycrmid) ORDER BY out_id DESC;
		SET @j=@j+1+@record_step;
	END WHILE;

	UPDATE ld_salestarget SET targetyear=YEAR(CURDATE());

	
	UPDATE ld_account a
	LEFT JOIN (
		SELECT
			accountid,
			MAX(nextContactDate) AS nextContactDate
		FROM ld_contactrecords 
		WHERE deleted=0
			AND accountid>0
		GROUP BY accountid
	) b ON b.accountid=a.accountid
	SET 
		a.nextcontactdate=b.nextContactDate;

	SET @disable_triggers=NULL;
	

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `receivedamountformaintable` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `receivedamountformaintable`()
begin 
 declare ttablename varchar(50);
 declare ttabid int(11);
declare bblock int(11);
	declare tmp_columnname varchar(50);
 declare done  int  default 0;
	declare cur3 CURSOR FOR select  ld_field.tablename,ld_field.tabid,ld_field.block  from
			ld_field inner join ld_producttoolfield on ld_field.tabid=ld_producttoolfield.tabid 
			where  ld_producttoolfield.columnname='quantity' and 
					(sourcemodule is null or sourcemodule='') and ld_field.columnname='smownerid';
	declare continue handler  for not   found  SET done =1;
	open cur3;
	fetch cur3 into ttablename,ttabid,bblock;
   set @disable_triggers ='a';

	loop2: while  done<>1 DO
		set tmp_columnname='received_amount';
		IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=ttablename AND COLUMN_NAME=tmp_columnname) THEN
			call AddColumn(ttablename,'received_amount','decimal','20','0');
			call AddColumn(ttablename,'receivable_balance','decimal','20','0');
			set @sql=Concat('alter table ', ttablename,' modify received_amount decimal(20,6)');
			prepare stmt from @sql;
			execute stmt;
			set @sql=Concat('alter table ', ttablename,' modify receivable_balance decimal(20,6)');
			prepare stmt1 from @sql;
			execute stmt1;
			
			set @sql=concat('update ',ttablename,' set receivable_balance=total 
				where not exists(select 1 from ld_field where tablename="',ttablename,'" and columnname="receivable_balance")');
				prepare updatestmt from @sql;
		   execute updatestmt;
	    	deallocate  prepare  updatestmt;
			
			set @sql=Concat("insert into ld_field(tabid,columnname,tablename,generatedtype,uitype,fieldname,fieldlabel,readonly,presence,defaultvalue,sequence,block,displaytype,typeofdata,quickcreate,quickcreatesequence,info_type,masseditable,helpinfo,fieldonly,approve_demand,is_checkimportfield,bigtype,datarang,maxrowsshow,allowedit,allowedit_presence,allowcreate,allowcreate_presence,allowdetail_presence)
							select ",ttabid,",'received_amount','",ttablename,"',1,71,'received_amount','已收总额',0,1,NULL,1,",bblock,",2,'N~O~25,2',0,NULL,NULL,1,NULL,0,2,0,'currency',NULL,0,'no','no','no','no','no' from dual
							where not exists (select 1 from ld_field where tabid=",ttabid," and tablename='",ttablename,"' and columnname='received_amount')");
			prepare stmt2 from @sql;
			execute stmt2;
			select fieldid into @fieldid from ld_field where tabid=ttabid and columnname='received_amount';
			set @sql=Concat('insert into ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
								select "zh","ld_field",',ttabid,",",@fieldid,",'已收总额' from dual 		
							   where not exists(select 1 from ld_tranlabel where languagetype='zh' and tabid=",ttabid, " and relateid=",@fieldid
								," and trantable='ld_field')");
			prepare stmt3 from @sql;
			execute stmt3;
			deallocate  prepare  stmt3;
			set @sql=Concat('insert into ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
									select "en","ld_field",',ttabid,",",@fieldid,",'已收总额' from dual 		
									 where not exists(select 1 from ld_tranlabel where languagetype='en' and tabid=",ttabid, " and relateid=",@fieldid
									," and trantable='ld_field')");
			prepare stmt4 from @sql;
			execute stmt4;
			deallocate  prepare  stmt4;

			set @sql=Concat("insert into ld_field(tabid,columnname,tablename,generatedtype,uitype,fieldname,fieldlabel,readonly,presence,defaultvalue,sequence,block,displaytype,typeofdata,quickcreate,quickcreatesequence,info_type,masseditable,helpinfo,fieldonly,approve_demand,is_checkimportfield,bigtype,datarang,maxrowsshow,allowedit,allowedit_presence,allowcreate,allowcreate_presence,allowdetail_presence)
							select ",ttabid,",'receivable_balance','",ttablename,"',1,71,'receivable_balance','应收余额',0,1,NULL,1,",bblock,",2,'N~O~25,2',0,NULL,NULL,1,NULL,0,2,0,'currency',NULL,0,'no','no','no','no','no' from dual
							where not exists (select 1 from ld_field where tabid=",ttabid," and tablename='",ttablename,"' and columnname='receivable_balance')");
			prepare stmt5 from @sql;
			execute stmt5;

			select fieldid into @fieldid from ld_field where tabid=ttabid and columnname='receivable_balance';
			set @sql=Concat('insert into ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
								select "zh","ld_field",',ttabid,",",@fieldid,",'应收余额' from dual 		
							   where not exists(select 1 from ld_tranlabel where languagetype='zh' and tabid=",ttabid,
											" and relateid=",@fieldid
								," and trantable='ld_field')");
			prepare stmt6 from @sql;
			execute stmt6;
			deallocate  prepare  stmt6;
			set @sql=Concat('insert into ld_tranlabel(languagetype,trantable,tabid,relateid,fieldlabel)
									select "en","ld_field",',ttabid,",",@fieldid,",'应收余额' from dual 		
									 where not exists(select 1 from ld_tranlabel where languagetype='en' and tabid=",ttabid, " and relateid=",@fieldid
									," and trantable='ld_field')");
			prepare stmt7 from @sql;
			execute stmt7;
			deallocate  prepare  stmt7;
		end if ;
		
		set tmp_columnname='pay_amount';
		IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=ttablename AND COLUMN_NAME=tmp_columnname) THEN
			call AddColumn(ttablename,'pay_amount','decimal','20','0');
			call AddColumn(ttablename,'pay_balance','decimal','20','0');
			set @sql=Concat('alter table ', ttablename,' modify pay_amount decimal(20,6)');
			prepare stmt20 from @sql;
			execute stmt20;
			set @sql=Concat('alter table ', ttablename,' modify pay_balance decimal(20,6)');
			prepare stmt21 from @sql;
			execute stmt21;
			
			set @sql=concat('update ',ttablename,' set pay_balance=total 
				where not exists(select 1 from ld_field where tablename="',ttablename,'" and columnname="pay_balance")');
				prepare updatestmt2 from @sql;
		   execute updatestmt2;
	    	deallocate  prepare  updatestmt2;
			
