/*!50003 DROP PROCEDURE IF EXISTS `update_customreport_sqlchart` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_customreport_sqlchart`()
begin
IF NOT  EXISTS(SELECT * from ld_report_analysis_folder WHERE `name` = 'YoY_MoM') then
SELECT max(analysisfolder_id) INTO @folderid from ld_report_analysis_folder;
SELECT analysisfolder_id INTO @parent_id from ld_report_analysis_folder WHERE `name` = 'CustomEcharts';
INSERT INTO `ld_report_analysis_folder` (`analysisfolder_id`, `name`, `folderlabel_zh`, `folderlabel_en`, `parent_id`, `description`, `smcreatorid`, `createdtime`, `sequence`, `visible`, `systemdefault`, `version`, `modify_id`, `modify_time`, `deleted`, `allocatetype`, `depth`, `approveallocatetype`, `primaryname`) VALUES (@folderid + 1, 'YoY_MoM', '同比环比分析', 'YoY and MoM', @parent_id, '', '1', '2022-11-29 11:53:24', '4', 'yes', 'yes', '', '1', '2022-11-29 11:53:24', '0', '0', '2', '0', NULL);
UPDATE ld_customreport set analysisfolder_id = (@folderid + 1) WHERE primaryname LIKE '%_y_to_y' OR primaryname LIKE '%_m_to_m';
END IF;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_invoice_receivedamount_byinvoiceid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_invoice_receivedamount_byinvoiceid`(
	tmp_invoiceid INT(19)
)
BEGIN

	SET @cnt1=0;
	SELECT
		count(1) INTO @cnt1
	FROM (
		SELECT IFNULL(currency_id,1) AS currency_id FROM ld_invoice WHERE invoiceid=tmp_invoiceid
		UNION
		SELECT IFNULL(currency_id,1) FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0
		UNION
		SELECT 
			IFNULL(a.currency_id,1)
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END)
	) a;

	IF @cnt=1 THEN
		
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount) INTO @indir_cashtotal FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0;
		UPDATE ld_invoice SET received_amount=IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0) WHERE invoiceid=tmp_invoiceid;
	ELSE
		
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount/IFNULL(a.conversion_rate,1)) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount/IFNULL(conversion_rate,1)) INTO @indir_cashtotal FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0;
		UPDATE ld_invoice SET received_amount=(IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0))*IFNULL(conversion_rate,1) WHERE invoiceid=tmp_invoiceid;
	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_products_ststus1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_products_ststus1`(
)
begin

	declare done  int  default 0;
	declare tmpproductid int default 0;

	
	declare tmpdescription varchar(200) default null;

	
	declare curw CURSOR FOR SELECT productid,description FROM  ld_products;

	declare continue handler  for not   found  SET done =1;

	OPEN curw;
		Fetch curw INTO tmpproductid,tmpdescription;
		loop1: while  done<>1 DO
			
			
			SET @salesorderid=0;
			SELECT
				ld_salesorder.salesorderid INTO @salesorderid
			FROM ld_salesorder
			LEFT JOIN ld_salesorderdetail ON ld_salesorder.salesorderid=ld_salesorderdetail.id
			WHERE ld_salesorder.deleted=0 
				AND ld_salesorder.approvestatus='已批准'
				AND ld_salesorderdetail.productid=tmpproductid 
			ORDER BY ld_salesorder.signed_data DESC LIMIT 1;

			IF @salesorderid>0 THEN
			
				
				
				SET @service_end_date=NULL;
				SELECT
					IFNULL(ld_servicecontractsdetail.servicecontracts_end_date,'1900-01-01') INTO @service_end_date
				FROM ld_servicecontracts
				LEFT JOIN ld_servicecontractsdetail ON ld_servicecontracts.servicecontractsid=ld_servicecontractsdetail.id
				WHERE ld_servicecontracts.deleted=0 
					AND ld_servicecontractsdetail.productid=tmpproductid 
				ORDER BY ld_servicecontractsdetail.servicecontracts_end_date DESC LIMIT 1;
				
				IF @service_end_date='1900-01-01' THEN
					
					UPDATE ld_products SET description='已售' WHERE productid=tmpproductid;
				
				ELSEIF @service_end_date>=CURDATE() THEN
					
					UPDATE ld_products SET description='已租' WHERE productid=tmpproductid;
					
				ELSE
					
					UPDATE ld_products SET description='待售租' WHERE productid=tmpproductid;
				END IF;
			
			ELSE
				
				UPDATE ld_products SET description='待售租' WHERE productid=tmpproductid;
			END IF;

		Fetch curw INTO tmpproductid,tmpdescription;
		end while loop1;
	close curw;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_purchaseinvoice_receivedamount_bypurchaseinvoiceid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_purchaseinvoice_receivedamount_bypurchaseinvoiceid`(
	tmp_invoiceid INT(19)
)
BEGIN

	SET @cnt1=0;
	SELECT
		count(1) INTO @cnt1
	FROM (
		SELECT IFNULL(currency_id,1) AS currency_id FROM ld_purchaseinvoice WHERE purchaseinvoiceid=tmp_invoiceid
		UNION
		SELECT IFNULL(currency_id,1) FROM ld_sendpayment WHERE deleted=0 AND Purchaseorder_id=tmp_invoiceid AND IFNULL(actualamount,0)>0
		UNION
		SELECT 
			IFNULL(a.currency_id,1)
		FROM ld_sendcashbill a
		LEFT JOIN ld_sendcashbill2payment b ON a.sendcashbillid=b.sendcashbillid
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=84)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END)
	) a;

	IF @cnt=1 THEN
		
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount) INTO @dir_cashtotal
		FROM ld_sendcashbill a
		LEFT JOIN ld_sendcashbill2payment b ON a.sendcashbillid=b.sendcashbillid
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=84)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount) INTO @indir_cashtotal FROM ld_sendpayment WHERE deleted=0 AND Purchaseorder_id=tmp_invoiceid AND IFNULL(actualamount,0)>0;
		UPDATE ld_purchaseinvoice SET pay_amount=IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0) WHERE purchaseinvoiceid=tmp_invoiceid;
	ELSE
		
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount/IFNULL(a.conversion_rate,1)) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount/IFNULL(conversion_rate,1)) INTO @indir_cashtotal FROM ld_sendpayment WHERE deleted=0 AND Purchaseorder_id=tmp_invoiceid AND IFNULL(actualamount,0)>0;
		UPDATE ld_purchaseinvoice SET pay_amount=(IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0))*IFNULL(conversion_rate,1) WHERE purchaseinvoiceid=tmp_invoiceid;
	END IF;

end ;;
